"""Alert service for AegisAI security events."""

from dataclasses import dataclass


@dataclass(frozen=True)
class SecurityAlert:
    """Represent a security alert generated by AegisAI."""

    action: str
    risk_score: int
    threats: list[str]
    message: str


def create_alert(
    action: str,
    risk_score: int,
    threats: list[str],
) -> SecurityAlert | None:
    """Create an alert for high-risk security decisions."""

    if action not in {"warn", "block", "redact"}:
        return None

    threat_text = ", ".join(threats) if threats else "none"

    message = (
        f"AegisAI security alert: action={action}, "
        f"risk_score={risk_score}, threats={threat_text}"
    )

    return SecurityAlert(
        action=action,
        risk_score=risk_score,
        threats=threats,
        message=message,
    )